def find(table, x):
    lo, hi = 0, len(table) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if table[mid] == x:
            return mid
        if table[mid] < x:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1
